// apertureProbeAssets — THE PROBES' real scans, baked (engineer-chartered
// 2026-07-14, sealed 8fcb8d42…4a69). Generated ONCE from the designer's
// .handoff/assets scans by a one-off builder OUTSIDE the repo (the manifest
// discipline): exact Float32 vertex positions + Uint32 fan-triangulated
// indices, base64. NOT hand-edited, NEVER regenerated silently — the probes
// witness re-parses the real .obj files and asserts THIS module equal to
// them, byte for byte. A primitive stand-in cannot pass that gate.
/* eslint-disable */

export interface ProbeScan {
  positions: Float32Array; // xyz triples, the scan's own frame
  tris: Uint32Array; // triangle vertex indices
}

const decodeB64 = (b64: string): Uint8Array => {
  const B = (globalThis as { Buffer?: { from(s: string, enc: string): Uint8Array } }).Buffer;
  if (B) {
    return new Uint8Array(B.from(b64, 'base64'));
  }
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out;
};

